class RjTryPage extends HTMLElement {
  connectedCallback() {
    if (this._ready) return;
    this._ready = true;
    if (!document.querySelector('link[data-rj-fonts]')) {
      const l = document.createElement('link');
      l.rel = 'stylesheet';
      l.href = FONT_HREF;
      l.setAttribute('data-rj-fonts', '');
      document.head.appendChild(l);
    }
    // Wix gives the host (and its wrapper) the fixed editor height; let the page grow with its content.
    this.style.display = 'block';
    this.style.height = 'auto';
    if (this.parentElement) { this.parentElement.style.height = 'auto'; this.parentElement.style.minHeight = '0'; }
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = '<style>' + CSS + '</style>' + HTML;
    root.addEventListener('click', (e) => {
      const a = e.target.closest('[data-scroll]');
      if (!a) return;
      const t = root.getElementById(a.getAttribute('data-scroll'));
      if (t) { e.preventDefault(); t.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    });
    const bar = root.getElementById('sticky');
    const hero = root.querySelector('.hero-actions');
    const book = root.getElementById('book');
    if (bar && hero && book && 'IntersectionObserver' in window) {
      let heroOut = false, bookIn = false;
      const upd = () => {
        const on = heroOut && !bookIn;
        bar.classList.toggle('show', on);
        bar.setAttribute('aria-hidden', on ? 'false' : 'true');
        bar.querySelector('a').tabIndex = on ? 0 : -1;
      };
      new IntersectionObserver((en) => { heroOut = !en[0].isIntersecting && en[0].boundingClientRect.top < 0; upd(); }).observe(hero);
      new IntersectionObserver((en) => { bookIn = en[0].isIntersecting; upd(); }, { rootMargin: '0px 0px -30% 0px' }).observe(book);
    }
  }
}
